import { NextResponse } from "next/server";

type SensorEvent = {
  nodeId?: string;
  resident?: string;
  location?: string;
  eventType?: string;
  riskLevel?: string;
  confidence?: number;
  sensorData?: unknown;
  voiceCheckIn?: unknown;
  aiSummary?: string;
  source?: string;
  receivedAt?: string;
};

const globalStore = globalThis as typeof globalThis & {
  __echosyncLatestEvent?: SensorEvent;
  __echosyncEvents?: SensorEvent[];
};

export async function POST(request: Request) {
  try {
    const body = await request.json();

    const event: SensorEvent = {
      ...body,
      receivedAt: new Date().toISOString(),
    };

    globalStore.__echosyncLatestEvent = event;
    globalStore.__echosyncEvents = globalStore.__echosyncEvents || [];
    globalStore.__echosyncEvents.unshift(event);
    globalStore.__echosyncEvents = globalStore.__echosyncEvents.slice(0, 20);

    console.log("EchoSync sensor event received:", event);

    return NextResponse.json({
      ok: true,
      message: "Sensor event received",
      event,
    });
  } catch (error) {
    return NextResponse.json(
      {
        ok: false,
        error: "Invalid sensor event payload",
      },
      { status: 400 }
    );
  }
}

export async function GET() {
  return NextResponse.json({
    ok: true,
    latest: globalStore.__echosyncLatestEvent || null,
    events: globalStore.__echosyncEvents || [],
  });
}
import { NextResponse } from "next/server";

type CaregiverAlert = {
  nodeId?: string;
  resident?: string;
  location?: string;
  eventType?: string;
  riskLevel?: string;
  confidence?: number;
  reason?: string;
  sensorData?: unknown;
  voiceCheckIn?: unknown;
  aiSummary?: string;
  source?: string;
  timestamp?: string;
  receivedAt?: string;
};

const globalStore = globalThis as typeof globalThis & {
  __echosyncCaregiverLatest?: CaregiverAlert;
  __echosyncCaregiverAlerts?: CaregiverAlert[];
};

export async function POST(request: Request) {
  try {
    const body = await request.json();

    const alert: CaregiverAlert = {
      ...body,
      receivedAt: new Date().toISOString(),
    };

    globalStore.__echosyncCaregiverLatest = alert;
    globalStore.__echosyncCaregiverAlerts =
      globalStore.__echosyncCaregiverAlerts || [];

    globalStore.__echosyncCaregiverAlerts.unshift(alert);
    globalStore.__echosyncCaregiverAlerts =
      globalStore.__echosyncCaregiverAlerts.slice(0, 20);

    console.log("EchoSync caregiver alert received:", alert);

    return NextResponse.json({
      ok: true,
      message: "Caregiver alert received",
      latest: alert,
    });
  } catch {
    return NextResponse.json(
      {
        ok: false,
        error: "Invalid caregiver alert payload",
      },
      { status: 400 }
    );
  }
}

export async function GET() {
  return NextResponse.json({
    ok: true,
    latest: globalStore.__echosyncCaregiverLatest || null,
    alerts: globalStore.__echosyncCaregiverAlerts || [],
  });
}
import { NextResponse } from "next/server";

type NodeControlState = {
  pauseLowRiskMonitoring: boolean;
  reason: string | null;
  durationMinutes: number | null;
  updatedAt: string | null;
};

const globalStore = globalThis as typeof globalThis & {
  __echosyncNodeControl?: NodeControlState;
};

function getDefaultState(): NodeControlState {
  return {
    pauseLowRiskMonitoring: false,
    reason: null,
    durationMinutes: null,
    updatedAt: null,
  };
}

export async function GET() {
  const state = globalStore.__echosyncNodeControl || getDefaultState();

  return NextResponse.json({
    ok: true,
    ...state,
  });
}

export async function POST(request: Request) {
  try {
    const body = await request.json();

    const state: NodeControlState = {
      pauseLowRiskMonitoring: Boolean(body.pauseLowRiskMonitoring),
      reason: body.reason || null,
      durationMinutes: body.durationMinutes || null,
      updatedAt: new Date().toISOString(),
    };

    globalStore.__echosyncNodeControl = state;

    console.log("EchoSync node control updated:", state);

    return NextResponse.json({
      ok: true,
      message: "Node control updated",
      ...state,
    });
  } catch {
    return NextResponse.json(
      {
        ok: false,
        error: "Invalid node control payload",
      },
      { status: 400 }
    );
  }
}

